/**
 * Tests parameter substitution algorithm to make sure the input sql is NOT transformed
 * especially escape characters.
 */
@Test
public void testParamSubstitute() {
    String[][] sqlNrtns = { { "like '5@%' escape '@'", "[]" }, //                {
    //                    "like '%#####_#%%' escape '#' WHERE ? = 'ab",
    //                    "[1]"
    //                },
    { "SELECT 'TRUE' AS VAL FROM DUAL WHERE '\\' = ? AND 'Y' = 'Y'", "[1]" }, { "like '*_n' escape '*' WHERE x = ? and y = ?", "[1, 2]" }, { "like '%80@%%' escape '@' WHERE x = ? and y = ? or z=?", "[1, 2, 3]" }, { "like '*_sql**%' escape '*", "[]" }, { "SELECT 'TRUE' AS VAL FROM DUAL WHERE '\\' = ?", "[1]" }, { "SELECT * FROM (" + "SELECT FOLDER_ID, SYS_CONNECT_BY_PATH(NAME,'\\') AS PATH FROM PROJECT_FOLDER " + "START WITH PARENT_ID IS NULL CONNECT BY PRIOR FOLDER_ID = PARENT_ID" + ") WHERE PATH LIKE ?", "[1]" } };
    try {
        List<Integer> paramOrder = new ArrayList<>();
        for (String[] sqlNrtn : sqlNrtns) {
            paramOrder.clear();
            String rtnSql = SQLStoreQuery.substituteParams(sqlNrtn[0], paramOrder);
            assertEquals(sqlNrtn[0], rtnSql);
            assertEquals(sqlNrtn[1], paramOrder.toString());
        }
    } catch (IOException e) {
        fail("Unexpected Exception:" + e);
    }
}

/**
 * Tests exception collection returns from UpdateManager flush method is in
 * the order the original exceptions are thrown.
 */
@Test
public void testAddRetrieve() {
    Collection states = new ArrayList<OpenJPAStateManager>();
    states.add(new TestOpenJPAStateManager());
    Collection exceps = updMgr.flush(states, new TestJDBCStore());
    assertEquals(3, exceps.size());
    Iterator<Exception> itr = exceps.iterator();
    assertEquals(itr.next().getMessage(), "TestUpdateManager.populateRowManager");
    assertEquals(itr.next().getMessage(), "TestUpdateManager.flush");
    assertEquals(itr.next().getMessage(), "TestUpdateManager.customInsert");
}

/**
 * For databases that accept only short column names, test avoidance of
 * duplicate column names when populating the table with long column names.
 */
@Test
public void testPopulateWithLongColumnNames() {
    MappingDefaultsImpl mapping = new MappingDefaultsImpl();
    JDBCConfiguration conf = new JDBCConfigurationImpl(false, false);
    conf.setDBDictionary("oracle");
    mapping.setConfiguration(conf);
    Table table = new Table("testtable", null);
    Column[] cols = new Column[3];
    cols[0] = new Column("longnamelongnamelongnamelongnamelongnamelongname1", null);
    cols[1] = new Column("longnamelongnamelongnamelongnamelongnamelongname2", null);
    cols[2] = new Column("longnamelongnamelongnamelongnamelongnamelongname3", null);
    MappingRepository mr = new MappingRepository();
    mr.setConfiguration(conf);
    Version version = new Version(new ClassMapping(String.class, mr));
    mapping.populateColumns(version, table, cols);
    assertNotEquals("column names are conflicted : " + cols[0].getName(), cols[0].getName(), cols[1].getName());
    assertNotEquals("column names are conflicted : " + cols[0].getName(), cols[0].getName(), cols[2].getName());
    assertNotEquals("column names are conflicted : " + cols[1].getName(), cols[1].getName(), cols[2].getName());
}

