    ((FormatPreservingProperties) p2).setDefaultEntryDelimiter('=');
    ((FormatPreservingProperties) p2).setAddWhitespaceAfterDelimiter(false);
    String[] values = new String[] { "x", "x" + LS + "y", "x\\ny", "x\ty", "x\\ty", "x\fy", "x\\fy", "x\ry", "x\\ry", "C:\\Foo Bar\\Baz", randomString(5).replace('a', '\\'), randomString(500).replace('a', '\\'), randomString(5000).replace('a', '\\') };
