/**
 * First we create a schema mapping with boolean representation as CHAR(1).
 * Then we create an entry.
 * After that we create a diff from the entity to the current DB.
 * This should result in an empty diff.
 */
@Test
public void testSchemaCreation() throws Exception {
    Map<String, Object> emfProps = getPropertiesMap(EntityBoolChar.class, "openjpa.jdbc.SynchronizeMappings", "buildSchema(ForeignKeys=true, SchemaAction='add,deleteTableContents')", "openjpa.jdbc.DBDictionary", "(BitTypeName=CHAR(1),BooleanTypeName=CHAR(1),BooleanRepresentation=STRING_10)");
    {
        // stage 1. Create the DB and insert a line into it
        OpenJPAEntityManagerFactorySPI openjpaEmf = createNamedOpenJPAEMF("test", null, emfProps);
        OpenJPAEntityManagerSPI em = openjpaEmf.createEntityManager();
        assertNotNull(em);
        em.getTransaction().begin();
        EntityBoolChar val = new EntityBoolChar();
        val.setDummy(true);
        em.persist(val);
        em.getTransaction().commit();
        int id = val.getId();
        em.close();
        OpenJPAEntityManagerSPI em2 = openjpaEmf.createEntityManager();
        assertNotNull(em2);
        EntityBoolChar val2 = em2.find(EntityBoolChar.class, id);
        assertNotNull(val2);
        assertNotEquals(val, val2);
        openjpaEmf.close();
    }
    {
        // now we create a 2nd EntityManagerFactory but with a different configuration
        // we switch the boolean representation to CHAR(1)
        OpenJPAEntityManagerFactorySPI openjpaEmf = createNamedOpenJPAEMF("test", null, emfProps);
        String metaDataFactory = openjpaEmf.getConfiguration().getMetaDataFactory();
        JDBCConfiguration jdbcConf = new JDBCConfigurationImpl();
        jdbcConf.setMetaDataFactory(metaDataFactory);
        String[] entityClassFiles = new String[1];
        URL entityClassUrl = this.getClass().getClassLoader().getResource(EntityBoolChar.class.getName().replace(".", "/") + ".class");
        entityClassFiles[0] = entityClassUrl.getFile();
        MappingTool.Flags flags = new MappingTool.Flags();
        flags.mappingWriter = new StringWriter();
        flags.action = MappingTool.ACTION_REFRESH;
        flags.schemaAction = SchemaTool.ACTION_REFRESH;
        flags.sqlWriter = new StringWriter();
        flags.schemaWriter = new StringWriter();
        boolean ok = MappingTool.run(jdbcConf, entityClassFiles, flags, this.getClass().getClassLoader());
        assertTrue(ok);
        assertTrue(flags.sqlWriter.toString().isEmpty());
    }
}

@Test
public void testDelimitIdentifiers() throws SQLException {
    Driver derbyDriver;
    try {
        Class derbyClazz = Class.forName("org.apache.derby.jdbc.EmbeddedDriver");
        derbyDriver = (Driver) derbyClazz.newInstance();
    } catch (Exception e) {
        // all fine
        System.out.println("Skipping Derby specific test because Derby cannot be found in ClassPath");
        return;
    }
    final PersistenceUnitInfoImpl persistenceUnitInfo = new PersistenceUnitInfoImpl();
    persistenceUnitInfo.setExcludeUnlistedClasses(true);
    persistenceUnitInfo.addManagedClassName(AllFieldTypes.class.getName());
    final BasicDataSource ds = new BasicDataSource();
    ds.setDriver(derbyDriver);
    ds.setUrl("jdbc:derby:memory:TestDelimitIdentifiers;create=true");
    persistenceUnitInfo.setNonJtaDataSource(ds);
    // reproducer for OPENJPA-2818 delimitIdentifiers=true,delimitedCase=lower,schemaCase=lower
    persistenceUnitInfo.setProperty("openjpa.jdbc.DBDictionary", LowercaseSchemaDerbyDBDictionary.class.getName());
    new PersistenceProviderImpl().generateSchema(persistenceUnitInfo, new HashMap<>());
    // try rebuild the schema
    new PersistenceProviderImpl().generateSchema(persistenceUnitInfo, new HashMap<>());
    final Map<String, Collection<String>> columns = new HashMap<>();
    final Collection<String> createdTables = new HashSet<>();
    try (final Connection connection = ds.getConnection()) {
        try (final ResultSet tables = connection.getMetaData().getTables(null, null, "TestDelimitIdentifiers$AllFieldTypes%", null)) {
            while (tables.next()) {
                final String table = tables.getString(3);
                createdTables.add(table);
            }
        }
        for (final String table : createdTables) {
            try (final Statement statement = connection.createStatement()) {
                try (final ResultSet rs = statement.executeQuery("select * from \"" + table + "\"")) {
                    final ResultSetMetaData metaData = rs.getMetaData();
                    final Set<String> columnNames = new HashSet<>();
                    columns.put(table, columnNames);
                    for (int i = 1; i <= metaData.getColumnCount(); i++) {
                        columnNames.add(metaData.getColumnName(i));
                    }
                }
            }
        }
    }
    final EntityManagerFactory entityManagerFactory = new PersistenceProviderImpl().createContainerEntityManagerFactory(persistenceUnitInfo, new HashMap());
    try {
        final AllFieldTypes entity = new AllFieldTypes();
        final AllFieldTypes entity2 = new AllFieldTypes();
        {
            final EntityManager em = entityManagerFactory.createEntityManager();
            em.getTransaction().begin();
            try {
                em.persist(entity2);
                entity.setArrayOfStrings(new String[] { "a", "b" });
                entity.setStringField("foo");
                entity.setIntField(10);
                entity.setSelfOneOne(entity2);
                em.persist(entity);
                em.getTransaction().commit();
            } catch (final RuntimeException re) {
                if (em.getTransaction().isActive()) {
                    em.getTransaction().rollback();
                }
                throw re;
            } finally {
                em.close();
            }
        }
        {
            final EntityManager em = entityManagerFactory.createEntityManager();
            try {
                assertEquals(2, em.createQuery("select x from TestDelimitIdentifiers$AllFieldTypes x").getResultList().size());
                assertEquals(1, em.createQuery("select x from TestDelimitIdentifiers$AllFieldTypes x where x.stringField = 'foo'").getResultList().size());
                assertEquals(0, em.createQuery("select x from TestDelimitIdentifiers$AllFieldTypes x where x.stringField = 'bar'").getResultList().size());
                assertEquals(1, em.createQuery("select x from TestDelimitIdentifiers$AllFieldTypes x where x.intField >= 10").getResultList().size());
            } finally {
                em.close();
            }
        }
    } finally {
        entityManagerFactory.close();
    }
    ds.close();
}

@Test
public void ddlInSnakeCase() throws SQLException {
    Driver derbyDriver;
    try {
        Class derbyClazz = Class.forName("org.apache.derby.jdbc.EmbeddedDriver");
        derbyDriver = (Driver) derbyClazz.newInstance();
    } catch (Exception e) {
        // all fine
        System.out.println("Skipping Derby specific test because Derby cannot be found in ClassPath");
        return;
    }
    final PersistenceUnitInfoImpl persistenceUnitInfo = new PersistenceUnitInfoImpl();
    persistenceUnitInfo.setExcludeUnlistedClasses(true);
    persistenceUnitInfo.addManagedClassName(MyEntity1.class.getName());
    persistenceUnitInfo.addManagedClassName(MyEntity2.class.getName());
    final BasicDataSource ds = new BasicDataSource();
    ds.setDriver(derbyDriver);
    ds.setUrl("jdbc:derby:memory:ddlInSnakeCase;create=true");
    persistenceUnitInfo.setJtaDataSource(ds);
    persistenceUnitInfo.setProperty("openjpa.jdbc.DBDictionary", "derby(javaToDbColumnNameProcessing=snake_case)");
    new PersistenceProviderImpl().generateSchema(persistenceUnitInfo, new HashMap<>());
    final Collection<String> createdTables = new HashSet<>();
    final Map<String, Collection<String>> columns = new HashMap<>();
    try (final Connection connection = ds.getConnection()) {
        try (final ResultSet tables = connection.getMetaData().getTables(null, null, "TestSnakeCaseDDL$MyEntity%", null)) {
            while (tables.next()) {
                final String table = tables.getString(3);
                createdTables.add(table);
            }
        }
        for (final String table : createdTables) {
            try (final Statement statement = connection.createStatement()) {
                try (final ResultSet rs = statement.executeQuery("select * from \"" + table + "\"")) {
                    final ResultSetMetaData metaData = rs.getMetaData();
                    final Set<String> columnNames = new HashSet<>();
                    columns.put(table, columnNames);
                    for (int i = 1; i <= metaData.getColumnCount(); i++) {
                        columnNames.add(metaData.getColumnName(i));
                    }
                }
            }
        }
    }
    final EntityManagerFactory entityManagerFactory = new PersistenceProviderImpl().createContainerEntityManagerFactory(persistenceUnitInfo, new HashMap());
    try {
        {
            final EntityManager em = entityManagerFactory.createEntityManager();
            em.getTransaction().begin();
            try {
                final MyEntity1 entity = new MyEntity1();
                entity.setFooBar("1");
                entity.setThisField(123);
                em.persist(entity);
                em.getTransaction().commit();
            } catch (final RuntimeException re) {
                if (em.getTransaction().isActive()) {
                    em.getTransaction().rollback();
                }
                throw re;
            } finally {
                em.close();
            }
        }
        {
            final EntityManager em = entityManagerFactory.createEntityManager();
            try {
                final MyEntity1 myEntity1 = em.find(MyEntity1.class, "1");
                assertNotNull(myEntity1);
                assertEquals("1", myEntity1.getFooBar());
                assertEquals(123, myEntity1.getThisField());
            } finally {
                em.close();
            }
        }
        try (final Connection connection = ds.getConnection();
            final Statement statement = connection.createStatement();
            final ResultSet rs = statement.executeQuery("select foo_bar, this_field from \"TestSnakeCaseDDL$MyEntity1\"")) {
            assertTrue(rs.next());
            assertEquals("1", rs.getString(1));
            assertEquals(123, rs.getInt(2));
            assertFalse(rs.next());
        }
    } finally {
        entityManagerFactory.close();
    }
    ds.close();
    assertEquals(2, columns.get("TestSnakeCaseDDL$MyEntity1").size());
    assertTrue(columns.get("TestSnakeCaseDDL$MyEntity1").contains("FOO_BAR"));
    assertTrue(columns.get("TestSnakeCaseDDL$MyEntity1").contains("THIS_FIELD"));
    assertEquals(singleton("ANOTHER_FIELD"), columns.get("TestSnakeCaseDDL$MyEntity2"));
}

@Test
public void testIndicesCreated() {
    JDBCConfiguration conf = (JDBCConfiguration) emf.getConfiguration();
    ClassMapping cls = conf.getMappingRepositoryInstance().getMapping(EntityWithIndices.class, null, true);
    Table table = cls.getTable();
    Index idx1 = table.getIndex(DBIdentifier.newIndex("idx_index1"));
    assertNotNull("Defined index should exist", idx1);
    assertFalse(idx1.isUnique());
    Index idx2 = table.getIndex(DBIdentifier.newIndex("idx_long"));
    assertNotNull("Defined index should exist", idx2);
    assertTrue(idx2.isUnique());
    Set<String> indexedCols = new HashSet<>();
    for (Index idx : table.getIndexes()) {
        for (Column col : idx.getColumns()) {
            indexedCols.add(col.getIdentifier().getName());
        }
    }
    assertTrue(indexedCols.contains("INDEX1"));
    assertTrue(indexedCols.contains("LONG_NAME"));
    assertFalse(indexedCols.contains("NAME"));
    // test multi column index without spaces
    assertIndexColumns(table, "idx_wo_spaces", "INDEX1", "COL2", "COL3");
    // test multi column index without spaces
    assertIndexColumns(table, "idx_with_spaces", "LONG_NAME", "COL2", "COL3");
}

